(253430, 16970, 5212, '<td valign="top">Your title helps this a lot.  beautiful shot 7</td>', 'Your title helps this a lot.  beautiful shot 7', '2003-04-03 03:05:03.000000', NULL, 1),
(253432, 16916, 5212, '<td valign="top">I am upping my score on this one to a ten after reviewing it again.  Good luck!!</td>', 'I am upping my score on this one to a ten after reviewing it again.  Good luck!!', '2003-04-03 03:06:32.000000', NULL, 1),
(253433, 16947, 5212, '<td valign="top">I finally got this one.  It''s your self-portrait??  ha, good one.  7</td>', 'I finally got this one.  It''s your self-portrait??  ha, good one.  7', '2003-04-03 03:07:20.000000', NULL, 1),
(253435, 16941, 5212, '<td valign="top">Great humorous shot.  Creative use of being allowed additional post-processing freedom.</td>', 'Great humorous shot.  Creative use of being allowed additional post-processing freedom.', '2003-04-03 03:08:48.000000', NULL, 1),
(253436, 16940, 5212, '<td valign="top">This compares to DPC chat being shut down.  Hope this wasn''t real.  Maybe a little less shadow in the upper part might improve this shot.</td>', 'This compares to DPC chat being shut down.  Hope this wasn''t real.  Maybe a little less shadow in the upper part might improve this shot.', '2003-04-03 03:09:56.000000', NULL, 1),
(253437, 16952, 5212, '<td valign="top">The post processing on this shot makes me think she''s a little eerie, too.</td>', 'The post processing on this shot makes me think she''s a little eerie, too.', '2003-04-03 03:11:07.000000', NULL, 1),
(253497, 16931, 1379, '<td valign="top">That''s a pretty funny idea... and with a young enough victim, you could really get some milage out of this.  No, wait, I probably would have fallen for it, too...</td>', 'That''s a pretty funny idea... and with a young enough victim, you could really get some milage out of this.  No, wait, I probably would have fallen for it, too...', '2003-04-03 08:29:27.000000', NULL, 1),
(253525, 16905, 6600, '<td valign="top">Great idea, pulled it off ''to'' well (LOL).  Good job!</td>', 'Great idea, pulled it off ''to'' well (LOL).  Good job!', '2003-04-03 09:51:53.000000', NULL, 1),
(253542, 16978, 7190, '<td valign="top">Great</td>', 'Great', '2003-04-03 10:19:35.000000', NULL, 1),
(253544, 16941, 7190, '<td valign="top">Love it.. made me laugh and how did you distort only the one face?</td>', 'Love it.. made me laugh and how did you distort only the one face?', '2003-04-03 10:22:11.000000', NULL, 1),
(253617, 16986, 2667, '<td valign="top">Now thats a practical joke!  Was this photoshop work at all? It looks so real, as if the fire department staged it for some event... Either way, very nicely done.</td>', 'Now thats a practical joke!  Was this photoshop work at all? It looks so real, as if the fire department staged it for some event... Either way, very nicely done.', '2003-04-03 13:01:47.000000', NULL, 1),
(253618, 16978, 2667, '<td valign="top">I like the abstract shapes. Kinda scary though! Overall great shot.</td>', 'I like the abstract shapes. Kinda scary though! Overall great shot.', '2003-04-03 13:02:53.000000', NULL, 1),
(253619, 16916, 2667, '<td valign="top">Sometimes the oldest gags are the best! Well done.</td>', 'Sometimes the oldest gags are the best! Well done.', '2003-04-03 13:03:36.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(253700, 16947, 3102, '<td valign="top">My favorite one of the challenge -- and my only 10!  Great work -- very funny!</td>', 'My favorite one of the challenge -- and my only 10!  Great work -- very funny!', '2003-04-03 15:36:14.000000', NULL, 1),
(253703, 16983, 3102, '<td valign="top">Very clever -- it''s nice to see that someone has more spare time than I do!  :)</td>', 'Very clever -- it''s nice to see that someone has more spare time than I do!  :)', '2003-04-03 15:37:31.000000', NULL, 1),
(253714, 16954, 5266, '<td valign="top">Finally - a funny practical joke!!  Even though I can see your editing, you get a 9 from me.  Original - and it certainly meets the challenge</td>', 'Finally - a funny practical joke!!  Even though I can see your editing, you get a 9 from me.  Original - and it certainly meets the challenge', '2003-04-03 16:19:52.000000', NULL, 1),
(253716, 16983, 5266, '<td valign="top">Good work with the CNN text - and I wouldn''t put it past them to come up with something like this!!  Like the lighting</td>', 'Good work with the CNN text - and I wouldn''t put it past them to come up with something like this!!  Like the lighting', '2003-04-03 16:20:33.000000', NULL, 1),
(253717, 16978, 5266, '<td valign="top">Great focus on the pin - and I really like the star filter effect.  I think I have the same desk chair that you do!!</td>', 'Great focus on the pin - and I really like the star filter effect.  I think I have the same desk chair that you do!!', '2003-04-03 16:21:07.000000', NULL, 1),
(253718, 16946, 5266, '<td valign="top">A good standard practical joke!!  Nice lighting, but the pullee could use a manicure.</td>', 'A good standard practical joke!!  Nice lighting, but the pullee could use a manicure.', '2003-04-03 16:21:46.000000', NULL, 1),
(253719, 16913, 5266, '<td valign="top">Nice detail on the tack - would have been nice if this was on a chair or bench (or we could tell it was on a seat of some sort).</td>', 'Nice detail on the tack - would have been nice if this was on a chair or bench (or we could tell it was on a seat of some sort).', '2003-04-03 16:22:26.000000', NULL, 1),
(253720, 16982, 5266, '<td valign="top">Finally - an actual practical joke that took place on April Fool''s Day - not a set up - or at least it doesn''t seem that way.  Sort of snapshotty, but I got a chuckle out of it.</td>', 'Finally - an actual practical joke that took place on April Fool''s Day - not a set up - or at least it doesn''t seem that way.  Sort of snapshotty, but I got a chuckle out of it.', '2003-04-03 16:23:28.000000', NULL, 1),
(253722, 16930, 5266, '<td valign="top">Are you giving me the finger???  LOL!!  Good effect on the "bloody" stump of a finger in the box.  Great lighting.  But get a manicure next time you want a closeup of your hand!!</td>', 'Are you giving me the finger???  LOL!!  Good effect on the "bloody" stump of a finger in the box.  Great lighting.  But get a manicure next time you want a closeup of your hand!!', '2003-04-03 16:24:24.000000', NULL, 1),
(253724, 16990, 5266, '<td valign="top">Sorry - don''t feel this meets the challenge.  Not a practical joke in my mind.  Just an ornament</td>', 'Sorry - don''t feel this meets the challenge.  Not a practical joke in my mind.  Just an ornament', '2003-04-03 16:25:46.000000', NULL, 1),
(253725, 16970, 5266, '<td valign="top">Ooops - you get a 1!!</td>', 'Ooops - you get a 1!!', '2003-04-03 16:26:04.000000', NULL, 1),
(253726, 16925, 5266, '<td valign="top">No it doesn''t.  I don''t think this is a picture - it seems more like a computer generated something or other.</td>', 'No it doesn''t.  I don''t think this is a picture - it seems more like a computer generated something or other.', '2003-04-03 16:26:38.000000', NULL, 1),
(253727, 16926, 5266, '<td valign="top">Darn, this is a very boring photo.  Without the title there would be no joke at all.</td>', 'Darn, this is a very boring photo.  Without the title there would be no joke at all.', '2003-04-03 16:27:10.000000', NULL, 1),
(253728, 16918, 5266, '<td valign="top">Too much movement in the subjects - funny idea - don''t like the background.</td>', 'Too much movement in the subjects - funny idea - don''t like the background.', '2003-04-03 16:27:47.000000', NULL, 1),
(253729, 16989, 5266, '<td valign="top">And the practical joke is?   It''s really a man?  I don''t get it.</td>', 'And the practical joke is?   It''s really a man?  I don''t get it.', '2003-04-03 16:28:09.000000', NULL, 1),
(253738, 16947, 6900, '<td valign="top">Definitely one of the funniest and well executed pics of the challenge.  Funny idea, too.  I like the photoshop lighting trick and it works very well for this pic.</td>', 'Definitely one of the funniest and well executed pics of the challenge.  Funny idea, too.  I like the photoshop lighting trick and it works very well for this pic.', '2003-04-03 16:50:34.000000', NULL, 1),
(253740, 16978, 6900, '<td valign="top">Clear picture of what''s going on - great addition of light - OUCH.</td>', 'Clear picture of what''s going on - great addition of light - OUCH.', '2003-04-03 16:51:28.000000', NULL, 1),
(253741, 16958, 6900, '<td valign="top">Would''ve been funnier with an arm reaching into the picture to follow the directions - good shot though.</td>', 'Would''ve been funnier with an arm reaching into the picture to follow the directions - good shot though.', '2003-04-03 16:52:26.000000', NULL, 1),
(253742, 16941, 6900, '<td valign="top">At least you get a chance to make pics like this when the deadline is 24 hours!  Funny shot.</td>', 'At least you get a chance to make pics like this when the deadline is 24 hours!  Funny shot.', '2003-04-03 16:55:23.000000', NULL, 1),
(253762, 16986, 1563, '<td valign="top">Excellent Joke, I''m a firefighter and I found this very funny. :)  keep up the good work.<br/>The picture also is well set up.  Nice movement in the background.</td>', 'Excellent Joke, I''m a firefighter and I found this very funny. :)  keep up the good work.The picture also is well set up.  Nice movement in the background.', '2003-04-03 17:41:21.000000', NULL, 1),
(253767, 16947, 4517, '<td valign="top">Great effect. This must of been hard to do.10</td>', 'Great effect. This must of been hard to do.10', '2003-04-03 17:54:14.000000', NULL, 1),
(253845, 16905, 1863, '<td valign="top">norty! I don''t get it! I like the lighting,. and the background... well done...</td>', 'norty! I don''t get it! I like the lighting,. and the background... well done...', '2003-04-03 21:24:08.000000', NULL, 1),
(253850, 16978, 3084, '<td valign="top">way cool image, great highlight</td>', 'way cool image, great highlight', '2003-04-03 21:56:57.000000', NULL, 1),
(253855, 16944, 4159, '<td valign="top">I didn''t get this at first, must be thick-headed.  Nice concept.</td>', 'I didn''t get this at first, must be thick-headed.  Nice concept.', '2003-04-03 22:08:58.000000', NULL, 1),
(253973, 16971, 6892, '<td valign="top">Damn, you sure have imagination...</td>', 'Damn, you sure have imagination...', '2003-04-04 02:49:17.000000', NULL, 1),
