(253976, 16907, 6892, '<td valign="top">I''ve heard of worse being added to a cup of tea! Well done.</td>', 'I''ve heard of worse being added to a cup of tea! Well done.', '2003-04-04 02:55:01.000000', NULL, 1),
(253977, 16983, 6892, '<td valign="top">Very imaginative.</td>', 'Very imaginative.', '2003-04-04 02:56:35.000000', NULL, 1),
