(253980, 16978, 6892, '<td valign="top">Ouch!</td>', 'Ouch!', '2003-04-04 02:58:24.000000', NULL, 1),
(254048, 16958, 3585, '<td valign="top">Simple and effective composition, calls imediatly for all the possible worst things that could be spelled out on this piece of paper.  Very entertaining. 8</td>', 'Simple and effective composition, calls imediatly for all the possible worst things that could be spelled out on this piece of paper.  Very entertaining. 8', '2003-04-04 08:24:15.000000', NULL, 1),
